pub(super) fn joining_type(letter: char) -> Option<JoiningType> {
    JOINING_TYPES
        .binary_search_by_key(&letter, |&(entry, _)| entry)
        .ok()
        .and_then(|index| JOINING_TYPES.get(index))
        .map(|&(_, kind)| kind)
}

pub(super) fn joined_form(letter: char, form: JoinForm) -> Option<char> {
    if form == JoinForm::Isolated {
        return None;
    }
    JOINED_FORMS.iter().find(|&&(entry, entry_form, _)| entry == letter && entry_form == form).map(|&(_, _, point)| point)
}
